.v-organism__conversation .v-organism__bubble.-tail::before {background:var(--mfill);}
.v-organism[data-kind="chat"] .v-organism__composer[data-slot] {background:var(--v-beige);box-shadow:none;border:0;border-radius:24px;}
.v-organism[data-kind="chat"] .v-organism__composer [data-slot="input-group-input"] {font-size:12px;padding-inline:15px;}
.v-organism[data-kind="chat"] .v-organism__composer [data-slot="input-group-button"] {background:var(--v-pink);color:var(--v-on-accent);width:34px;height:34px;min-width:34px;padding:0;margin-right:8px;}
.v-organism__local-note {text-align:center;font-size:9px;line-height:1.4;color:var(--v-text-2);}

/* Focus is a real local clock, with a calm typographic centre. */
.v-organism[data-kind="focus"] .v-organism__surface {border-radius:29px;background:var(--v-paper);}
.v-organism__focus-heading .v-meta {font-size:9px;line-height:1.3;letter-spacing:.09em;color:var(--v-text-2);font-weight:600;}
.v-organism__focus-heading [data-slot="card-title"] {white-space:normal;font-size:21px;line-height:1.15;letter-spacing:-.025em;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.v-organism__focus-art {display:grid;place-items:center;}
.v-organism__focus-art [data-slot="shape"] {width:65px;height:65px;--c:var(--v-yellow);rotate:-13deg;}
.v-organism__clock {display:grid;justify-items:center;align-content:center;gap:13px;}
.v-organism[data-kind="focus"] .v-organism__clock [data-slot="typography-meta"][role="timer"] {font:500 clamp(48px,8vw,64px)/1 var(--font-display);letter-spacing:-.055em;font-variant-numeric:tabular-nums;color:var(--v-text);white-space:nowrap;}
.v-organism__clock [role="timer"] > span {color:var(--v-text-2);padding-inline:3px;}
.v-organism__clock > .v-meta:last-child {font-size:11px;color:var(--v-text-2);}
.v-organism[data-kind="focus"] .v-organism__progress [data-slot="progress"] {height:7px;}
.v-organism__focus-description {font-size:12px;line-height:1.5;text-align:center;color:var(--v-text-2);display:flex;align-items:center;justify-content:center;}
.v-organism[data-kind="focus"] [data-assembly-part="primary"] {font-size:13px;}

/* An invitation is a small event card; the RSVP stays on the current page. */
.v-organism[data-kind="invite"] .v-organism__surface {border-radius:29px;background:var(--v-paper);}
.v-organism__invite-cover {padding:0;overflow:hidden;border-radius:23px;}
.v-organism__invite-cover > [data-slot="card-content"] {height:100%;position:relative;overflow:hidden;display:flex;align-items:center;justify-content:flex-end;padding:22px;}
.v-organism__invite-cover [data-slot="shape"] {position:absolute;left:-18px;top:-20px;width:145px;height:145px;--c:var(--v-pink);rotate:15deg;}
.v-organism__invite-cover [data-slot="shape"]:nth-child(2) {left:70px;top:34px;width:83px;height:110px;--c:var(--v-yellow);rotate:-19deg;}
.v-organism[data-kind="invite"] .v-organism__invite-cover [data-slot="typography-meta"] {position:relative;max-width:12ch;font-size:11px;line-height:1.5;font-weight:600;letter-spacing:.045em;color:var(--v-on-accent);}
.v-organism__invite-heading [data-slot="card-title"] {font-size:23px;white-space:normal;line-height:1.15;letter-spacing:-.035em;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}
.v-organism__invite-heading [data-slot="card-description"] {font-size:12px;line-height:1.5;}
.v-organism__event-details {display:grid;gap:10px;align-content:center;}
.v-organism__event-details .v-meta {display:flex;align-items:center;gap:9px;font-size:11px;line-height:1.4;color:var(--v-text-2);}
.v-organism__event-details .v-icon {width:14px;height:14px;flex:none;}
.v-organism__participants {display:flex;align-items:center;gap:13px;}
.v-organism__avatar-stack {display:flex;padding-left:0;}
.v-organism__avatar-stack [data-slot="avatar"] {width:30px;height:30px;font-size:9px;border:3px solid var(--v-paper);margin-left:-7px;}
.v-organism__avatar-stack [data-slot="avatar"]:first-child {margin-left:0;}
.v-organism__participants > .v-meta {font-size:11px;color:var(--v-text-2);}
.v-organism__invite-status {font-size:11px;line-height:1.5;color:var(--v-text-2);}
.v-organism[data-kind="invite"] [data-assembly-part="primary"],.v-organism[data-kind="invite"] [data-assembly-part="secondary"] {font-size:11px;padding-inline:10px;}

}
